from pathlib import Path
import base64, gzip, sys

ROOT = Path(__file__).resolve().parents[1]
ENGINE_PATH = ROOT / "supabase/functions/kdk-free-program/engine.mjs"
INDEX_PATH = ROOT / "supabase/functions/kdk-free-program/index.ts"
PREVIEW_PATH = ROOT / "app/program/preview/page.tsx"
QUALITY_PATH = ROOT / "supabase/functions/kdk-free-program/quality-audit.mjs"

ENGINE_B64 = ""
QUALITY_B64 = ""

def decode(payload: str) -> str:
    return gzip.decompress(base64.b64decode(payload)).decode("utf-8")

def replace_once(path: Path, old: str, new: str):
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count == 0 and new in text:
        return
    if count != 1:
        raise SystemExit(f"{path} expected exactly one {old!r}, found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")

current = ENGINE_PATH.read_text(encoding="utf-8")
if 'export const ENGINE_VERSION = "FREE_ENGINE_V1.2";' not in current:
    if 'export const ENGINE_VERSION = "FREE_ENGINE_V1.1";' not in current:
        raise SystemExit("Unexpected engine base; refusing to overwrite")
    ENGINE_PATH.write_text(decode(ENGINE_B64), encoding="utf-8")

replace_once(INDEX_PATH, 'const EXPECTED_ENGINE_VERSION = "FREE_ENGINE_V1.1";', 'const EXPECTED_ENGINE_VERSION = "FREE_ENGINE_V1.2";')
replace_once(PREVIEW_PATH, 'const EXPECTED_ENGINE_VERSION = "FREE_ENGINE_V1.1";', 'const EXPECTED_ENGINE_VERSION = "FREE_ENGINE_V1.2";')
QUALITY_PATH.write_text(decode(QUALITY_B64), encoding="utf-8")

print("FREE_ENGINE_V1.2 files applied")